    "huangbo_chuanxin": {
      "id": "huangbo_chuanxin",
      "title_zh": "黃檗山斷際禪師傳心法要",
      "title_pinyin": "Huángbò Shān Duànjì Chánshī Chuánxīn Fǎyào",
      "title_en": "The Zen Teaching of Huang Po: On the Transmission of Mind",
      "cbeta_id": "T2012A",
      "taisho_vol": 48,
      "author_zh": "黃檗希運 禪師 說 / 唐 相國 裴休 集",
      "author_en": "Chan Master Huangbo Xiyun (d. 850), Recorded by Prime Minister Pei Xiu",
      "era": "Tang Dynasty (c. 857 CE)",
      "genre": "Mind Essentials / Discourse (傳心法要)",
      "sections": [
        {
          "section_id": "one_mind",
          "title_zh": "一心法要：諸佛與眾生",
          "title_pinyin": "Yīxīn Fǎyào: Zhūfó Yǔ Zhòngshēng",
          "title_en": "The Doctrine of One Mind",
          "dialogue": [
            {
              "speaker": "Huangbo / 黃檗",
              "zh": "師謂休曰：「諸佛與一切眾生，唯是一心，更無別法。此心無始已來，不曾生不曾滅，不青不黃，無形無相，不屬有無，不計新舊，非長非短，非大非小，超過一切限量名言蹤跡對待。」",
              "pinyin": "Shī wèi Xiū yuē: 'Zhūfó yǔ yīqiè zhòngshēng, wéi shì yī xīn, gèng wú bié fǎ. Cǐ xīn wú shǐ yǐ lái, bù céng shēng bù céng miè, bù qīng bù huáng, wú xíng wú xiàng, bù shǔ yǒu wú, bù jì xīn jiù, fēi cháng fēi duǎn, fēi dà fēi xiǎo, chāoguò yīqiè xiànliàng míngyán zōngjī duìdài.'",
              "translations": {
                "blofeld": {
                  "text": "All the Buddhas and all sentient beings are nothing but the One Mind, beside which nothing exists. This Mind, which is without beginning, is unborn and indestructible. It is not green nor yellow, and has neither form nor appearance. It does not belong to the categories of things which exist or do not exist, nor can it be thought of in terms of new or old. It is neither long nor short, big nor small, for it transcends all limits, measures, names, traces and comparisons.",
                  "status": "verified_quotation",
                  "source": {
                    "work": "The Zen Teaching of Huang Po: On the Transmission of Mind, tr. John Blofeld",
                    "edition": "Rider & Co., 1958 (Chün Chou Record, teaching 1)",
                    "verification": "wording consistent across Grove Atlantic (publisher), Terebess reproduction, and two further mirrors, 2026-08-08",
                    "note": "Replaces a prior paraphrase ('nothing whatever but… besides which').",
                    "source_id": "blofeld-huangpo-1958",
                    "reference": "teaching 1"
                  }
                },
                "cleary": {
                  "text": "The Master said to Pei Xiu: All Buddhas and all sentient beings are only One Mind, with no other reality. This mind from beginningless time has never been born and never perishes; it is not blue or yellow, has no form or characteristics, belongs neither to existence nor nonexistence, cannot be reckoned as new or old, is neither long nor short, neither large nor small, transcending all limits, words, traces, and polarities.",
                  "status": "reconstruction_unverified"
                },
                "suzuki": {
                  "text": "All Buddhas and all sentient beings are nothing but the One Mind; there is no other Dharma. This Mind from beginningless past has never been produced, has never ceased to be.",
                  "status": "reconstruction_unverified"
                },
                "ai_literal": {
                  "text": "The Master said to Xiu: All Buddhas and all sentient beings are only One Mind, with no separate dharmas. This mind from beginningless time has not been born, has not perished, is not blue, not yellow, without form and without signs.",
                  "status": "ai_draft"
                }
              }
            },
            {
              "speaker": "Huangbo / 黃檗",
              "zh": "「當體便是，動念即乖。猶如虛空，無有邊際，不可度量。唯此一心即是佛，佛與眾生更無別異。」",
              "pinyin": "'Dāng tǐ biàn shì, dòng niàn jí guāi. Yóu rú xū kōng, wú yǒu biānjì, bù kě dùliàng. Wéi cǐ yī xīn jí shì fó, fó yǔ zhòngshēng gèng wú bié yì.'",
              "translations": {
                "blofeld": {
                  "text": "It is that which you see before you—begin to reason about it and you at once fall into error. It is like the boundless void which cannot be fathomed or measured. The One Mind alone is the Buddha, and there is no distinction between the Buddha and sentient things.",
                  "status": "verified_quotation",
                  "source": {
                    "work": "The Zen Teaching of Huang Po: On the Transmission of Mind, tr. John Blofeld",
                    "edition": "Grove Press (Part One: Chün Chou Record §1)",
                    "verification": "verbatim (span matching unit's zh) vs Terebess reproduction of Blofeld's text, 2026-08-08; prior reconstruction ended 'sentient beings' — Blofeld's wording is 'sentient things'",
                    "source_id": "blofeld-huangpo-1958",
                    "reference": "§1"
                  }
                },
                "cleary": {
                  "text": "Its very substance is it; to stir a thought is immediately to deviate. It is like open space, having no boundaries, immeasurable. This One Mind alone is Buddha; between Buddha and sentient beings there is no difference whatsoever.",
                  "status": "reconstruction_unverified"
                },
                "ai_literal": {
                  "text": "Its immediate embodiment is it; stirring a thought is instantly deviating. Like empty space, without edges or borders, not measurable. Only this One Mind is Buddha; Buddha and sentient beings have no other difference.",
                  "status": "ai_draft"
                }
              }
            }
          ]
        }
      ]
    },
